'use strict';

/**
* LAPACK routine to compute a plane rotation of a vector so that the diagonal is nonnegative.
*
* @module @stdlib/lapack/base/dlartgp
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlartgp = require( '@stdlib/lapack/base/dlartgp' );
*
* var out = new Float64Array( 3 );
* dlartgp( 1.0, 2.0, out );
* // out => <Float64Array>[ ~0.447, ~0.894, ~2.236 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlartgp = require( '@stdlib/lapack/base/dlartgp' );
*
* var out = new Float64Array( 3 );
* dlartgp.ndarray( 1.0, 2.0, out, 1, 0 );
* // out => <Float64Array>[ ~0.447, ~0.894, ~2.236 ]
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dlartgp;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dlartgp = main;
} else {
	dlartgp = tmp;
}


// EXPORTS //

module.exports = dlartgp;
